/**
 * @method
 * @name tx_fn_Check
 * @description Check 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Check = async function () {
    const sbmOptions = {
        id: "tx_fn_Check",
