///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_EduAppResultList_fmt_disclsEduCrsNm
 * @description grd Edu App Result List fmt discls Edu Crs Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_EduAppResultList_fmt_disclsEduCrsNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_EduAppResultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "ldMktTpCd") ?? '') : '');
        if (v === '6') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "disclsEduCrsNm") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "disclsEduCrsNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_EduAppResultList.disclsEduCrsNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name check
 * @description check 처리
 * @returns {void}
 * @hidden N
 */
scwin.check = function () {
    let roundRealVal = "";
    const roundVal = $c.util.getComponent('slc_sltEduRnd').getValue();
    const roundVal1 = $c.util.getComponent('slc_sltEduRnd1').getValue();
    const roundVal2 = $c.util.getComponent('slc_sltEduRnd2').getValue();
    const roundVal3 = $c.util.getComponent('slc_sltEduRnd3').getValue();
    const roundVal4 = $c.util.getComponent('slc_sltEduRnd4').getValue();
    const roundVal5 = $c.util.getComponent('slc_sltEduRnd5').getValue();
    const roundVal6 = $c.util.getComponent('slc_sltEduRnd6').getValue();
    const r_temp = $c.util.getComponent('slc_disclsEduApctTpCd').getValue();
    if (r_temp === "%") {
        roundRealVal = roundVal;
    } else {
        if (r_temp === "11") {
            roundRealVal = roundVal1;
        } else {
            if (r_temp === "12") {
                roundRealVal = roundVal2;
            } else {
                if (r_temp === "41") {
                    roundRealVal = roundVal3;
                } else {
                    if (r_temp === "42") {
                        roundRealVal = roundVal4;
                    } else {
                        if (r_temp === "81") {
                            roundRealVal = roundVal5;
                        } else {
                            if (r_temp === "82") {
                                roundRealVal = roundVal6;
                            }
                        }
                    }
                }
            }
        }
    }
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', roundRealVal);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const form = (document.eduAppResultForm || { elements: [] });
    scwin.check();
    $c.util.getComponent('dma_SearchReq').set('method', 'searchRstEduApplication');
    form.action = 'eduAppResult.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_Search();
    scwin.flag = true;
};

/**
 * @method
 * @name change
 * @description change 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.change = function (code) {
    const form = (document.eduAppResultForm || { elements: [] });
    if (code.value === '11') {
        scwin.edu_rnd.setStyle("display", 'none');
        scwin.edu_rnd1.setStyle("display", 'block');
        scwin.edu_rnd2.setStyle("display", 'none');
        scwin.edu_rnd3.setStyle("display", 'none');
        scwin.edu_rnd4.setStyle("display", 'none');
        scwin.edu_rnd5.setStyle("display", 'none');
        scwin.edu_rnd6.setStyle("display", 'none');
    } else {
        if (code.value === '12') {
            scwin.edu_rnd.setStyle("display", 'none');
            scwin.edu_rnd1.setStyle("display", 'none');
            scwin.edu_rnd2.setStyle("display", 'block');
            scwin.edu_rnd3.setStyle("display", 'none');
            scwin.edu_rnd4.setStyle("display", 'none');
            scwin.edu_rnd5.setStyle("display", 'none');
            scwin.edu_rnd6.setStyle("display", 'none');
        } else {
            if (code.value === '41') {
                scwin.edu_rnd.setStyle("display", 'none');
                scwin.edu_rnd1.setStyle("display", 'none');
                scwin.edu_rnd2.setStyle("display", 'none');
                scwin.edu_rnd3.setStyle("display", 'block');
                scwin.edu_rnd4.setStyle("display", 'none');
                scwin.edu_rnd5.setStyle("display", 'none');
                scwin.edu_rnd6.setStyle("display", 'none');
            } else {
                if (code.value === '42') {
                    scwin.edu_rnd.setStyle("display", 'none');
                    scwin.edu_rnd1.setStyle("display", 'none');
                    scwin.edu_rnd2.setStyle("display", 'none');
                    scwin.edu_rnd3.setStyle("display", 'none');
                    scwin.edu_rnd4.setStyle("display", 'block');
                    scwin.edu_rnd5.setStyle("display", 'none');
                    scwin.edu_rnd6.setStyle("display", 'none');
                } else {
                    if (code.value === '81') {
                        scwin.edu_rnd.setStyle("display", 'none');
                        scwin.edu_rnd1.setStyle("display", 'none');
                        scwin.edu_rnd2.setStyle("display", 'none');
                        scwin.edu_rnd3.setStyle("display", 'none');
                        scwin.edu_rnd4.setStyle("display", 'none');
                        scwin.edu_rnd5.setStyle("display", 'block');
                        scwin.edu_rnd6.setStyle("display", 'none');
                    } else {
                        if (code.value === '82') {
                            scwin.edu_rnd.setStyle("display", 'none');
                            scwin.edu_rnd1.setStyle("display", 'none');
                            scwin.edu_rnd2.setStyle("display", 'none');
                            scwin.edu_rnd3.setStyle("display", 'none');
                            scwin.edu_rnd4.setStyle("display", 'none');
                            scwin.edu_rnd5.setStyle("display", 'none');
                            scwin.edu_rnd6.setStyle("display", 'block');
                        } else {
                            scwin.edu_rnd.setStyle("display", 'block');
                            scwin.edu_rnd1.setStyle("display", 'none');
                            scwin.edu_rnd2.setStyle("display", 'none');
                            scwin.edu_rnd3.setStyle("display", 'none');
                            scwin.edu_rnd4.setStyle("display", 'none');
                            scwin.edu_rnd5.setStyle("display", 'none');
                            scwin.edu_rnd6.setStyle("display", 'none');
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name change2
 * @description change2 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.change2 = function (code) {
    const form = (document.eduAppResultForm || { elements: [] });
    if (code === '11') {
        scwin.edu_rnd.setStyle("display", 'none');
        scwin.edu_rnd1.setStyle("display", 'block');
        scwin.edu_rnd2.setStyle("display", 'none');
        scwin.edu_rnd3.setStyle("display", 'none');
        scwin.edu_rnd4.setStyle("display", 'none');
        scwin.edu_rnd5.setStyle("display", 'none');
        scwin.edu_rnd6.setStyle("display", 'none');
    } else {
        if (code === '12') {
            scwin.edu_rnd.setStyle("display", 'none');
            scwin.edu_rnd1.setStyle("display", 'none');
            scwin.edu_rnd2.setStyle("display", 'block');
            scwin.edu_rnd3.setStyle("display", 'none');
            scwin.edu_rnd4.setStyle("display", 'none');
            scwin.edu_rnd5.setStyle("display", 'none');
            scwin.edu_rnd6.setStyle("display", 'none');
        } else {
            if (code === '41') {
                scwin.edu_rnd.setStyle("display", 'none');
                scwin.edu_rnd1.setStyle("display", 'none');
                scwin.edu_rnd2.setStyle("display", 'none');
                scwin.edu_rnd3.setStyle("display", 'block');
                scwin.edu_rnd4.setStyle("display", 'none');
                scwin.edu_rnd5.setStyle("display", 'none');
                scwin.edu_rnd6.setStyle("display", 'none');
            } else {
                if (code === '42') {
                    scwin.edu_rnd.setStyle("display", 'none');
                    scwin.edu_rnd1.setStyle("display", 'none');
                    scwin.edu_rnd2.setStyle("display", 'none');
                    scwin.edu_rnd3.setStyle("display", 'none');
                    scwin.edu_rnd4.setStyle("display", 'block');
                    scwin.edu_rnd5.setStyle("display", 'none');
                    scwin.edu_rnd6.setStyle("display", 'none');
                } else {
                    if (code === '81') {
                        scwin.edu_rnd.setStyle("display", 'none');
                        scwin.edu_rnd1.setStyle("display", 'none');
                        scwin.edu_rnd2.setStyle("display", 'none');
                        scwin.edu_rnd3.setStyle("display", 'none');
                        scwin.edu_rnd4.setStyle("display", 'none');
                        scwin.edu_rnd5.setStyle("display", 'block');
                        scwin.edu_rnd6.setStyle("display", 'none');
                    } else {
                        if (code === '82') {
                            scwin.edu_rnd.setStyle("display", 'none');
                            scwin.edu_rnd1.setStyle("display", 'none');
                            scwin.edu_rnd2.setStyle("display", 'none');
                            scwin.edu_rnd3.setStyle("display", 'none');
                            scwin.edu_rnd4.setStyle("display", 'none');
                            scwin.edu_rnd5.setStyle("display", 'none');
                            scwin.edu_rnd6.setStyle("display", 'block');
                        } else {
                            scwin.edu_rnd.setStyle("display", 'block');
                            scwin.edu_rnd1.setStyle("display", 'none');
                            scwin.edu_rnd2.setStyle("display", 'none');
                            scwin.edu_rnd3.setStyle("display", 'none');
                            scwin.edu_rnd4.setStyle("display", 'none');
                            scwin.edu_rnd5.setStyle("display", 'none');
                            scwin.edu_rnd6.setStyle("display", 'none');
                        }
                    }
                }
            }
        }
    }
};

