/**
 * @method
 * @name excel_download
 * @description excel download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel_download = async function () {
    const form = (document.eduAppResultForm || { elements: [] });
    scwin.check();
    const eduTp = $c.util.getComponent('slc_disclsEduApctTpCd').getValue();
    if ("12" === eduTp || "42" === eduTp || "82" === eduTp) {
        $c.util.getComponent('dma_SearchReq').set('method', 'searchRstEduExcelApplicationChg');
    } else {
        $c.util.getComponent('dma_SearchReq').set('method', 'searchRstEduExcelApplication');
    }
    form.action = 'eduAppResult.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "07");
    await scwin.tx_excel_download();
};

/**
 * @method
 * @name execCheck
 * @description exec Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.execCheck = async function () {
    const frm = (document.eduAppResultForm || { elements: [] });
    let result_seq = "";
    let result_isurcd = "";
    let result_edutpcd = "";
    let result_chrgseq = "";
    for (let i = 0; i < $c.util.getComponent('dlt_EduAppResultList').getRowCount(); i++) {
        if ((['true', 'Y', '1'].indexOf(String($c.util.getComponent('dlt_EduAppResultList').getCellData(i, 'chbEdu'))) >= 0)) {
            let tmp = $c.util.getComponent('dlt_EduAppResultList').getCellData(i, 'chbEdu');
            tmp = tmp.split("/");
            const v1 = tmp[0];
            const v2 = tmp[1];
            const v3 = tmp[2];
            const v4 = tmp[3];
            if (result_seq === "") {
                result_seq = v1;
            } else {
                result_seq += "," + v1;
            }
            if (result_isurcd === "") {
                result_isurcd = v2;
            } else {
                result_isurcd += "," + v2;
            }
            if (result_edutpcd === "") {
                result_edutpcd = v3;
            } else {
                result_edutpcd += "," + v3;
            }
            if (result_chrgseq === "") {
                result_chrgseq = v4;
            } else {
                result_chrgseq += "," + v4;
            }
        }
    }
    $c.util.getComponent('dma_SearchReq').set('ChbResult_Seq', result_seq);
    $c.util.getComponent('dma_SearchReq').set('ChbResult_IsurCd', result_isurcd);
    $c.util.getComponent('dma_SearchReq').set('ChbResult_EduTpCd', result_edutpcd);
    $c.util.getComponent('dma_SearchReq').set('ChbResult_ChrgSeq', result_chrgseq);
    if ($c.util.getComponent('dma_SearchReq').get('ChbResult_Seq') === "") {
        await $c.win.alert("교육이력반영 대상이 선택되지 않았습니다.");
    } else {
        if (await $c.win.confirm("교육이력 반영을 진행하시겠습니까?")) {
            $c.util.getComponent('dma_SearchReq').set('method', 'registerDisclsEdu');
            frm.action = 'eduAppResult.do';
            $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "02");
            await scwin.tx_fn_Check();
        }
    }
};

/**
 * @method
 * @name checkAll
 * @description check All 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkAll = function () {
    const frm = (document.eduAppResultForm || { elements: [] });
    for (let i = 0; i < $c.util.getComponent('dlt_EduAppResultList').getRowCount(); i++) {
        if ((String((dma_SearchReq.get("chbAll") ?? (() => { throw new Error("unresolved:" + "dma_SearchReq.chbAll"); })()) || "") !== "")) {
            $c.util.getComponent('dlt_EduAppResultList').setCellData(i, 'chbEdu', ((true) ? 'true' : 'false'));
        } else {
            $c.util.getComponent('dlt_EduAppResultList').setCellData(i, 'chbEdu', ((false) ? 'true' : 'false'));
        }
    }
};
